namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalStars { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalStars / RatingCount : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new() { Id = 1, Category = "Breakfast", Title = "Fluffy Pancakes",
                Ingredients = "2 cups flour\n2 eggs\n1 cup milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
                Steps = "1. Mix dry ingredients together.\n2. Whisk eggs and milk, then combine with dry mix.\n3. Heat a buttered pan over medium heat.\n4. Pour batter and cook until bubbles form, then flip.\n5. Serve with maple syrup." },
            new() { Id = 2, Category = "Breakfast", Title = "Avocado Toast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\n1 tbsp lemon juice\nSalt and pepper\nRed pepper flakes",
                Steps = "1. Toast the bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread on toast and sprinkle with red pepper flakes." },
            new() { Id = 3, Category = "Lunch", Title = "Caesar Salad",
                Ingredients = "1 head romaine lettuce\n1/2 cup croutons\n1/4 cup parmesan\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons, shaved parmesan, and grilled chicken." },
            new() { Id = 4, Category = "Lunch", Title = "Grilled Cheese Sandwich",
                Ingredients = "2 slices bread\n2 slices cheddar cheese\n1 tbsp butter",
                Steps = "1. Butter the outside of each bread slice.\n2. Place cheese between the slices.\n3. Grill on medium heat until golden on both sides." },
            new() { Id = 5, Category = "Dinner", Title = "Spaghetti Bolognese",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 cloves garlic\n400g crushed tomatoes\n2 tbsp olive oil\nSalt, pepper, Italian herbs",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and brown.\n4. Stir in crushed tomatoes and herbs, simmer 20 minutes.\n5. Serve sauce over spaghetti." },
            new() { Id = 6, Category = "Dinner", Title = "Chicken Stir-Fry",
                Ingredients = "2 chicken breasts, sliced\n1 bell pepper\n1 cup broccoli\n2 tbsp soy sauce\n1 tbsp sesame oil\n1 clove garlic\nCooked rice",
                Steps = "1. Heat sesame oil in a wok over high heat.\n2. Cook chicken until browned.\n3. Add vegetables and garlic, stir-fry 3-4 minutes.\n4. Add soy sauce and toss.\n5. Serve over rice." },
            new() { Id = 7, Category = "Desserts", Title = "Chocolate Chip Cookies",
                Ingredients = "2 1/4 cups flour\n1 cup butter, softened\n3/4 cup sugar\n3/4 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
                Steps = "1. Cream butter and sugars together.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Drop spoonfuls on baking sheet.\n6. Bake at 375°F for 9-11 minutes." },
            new() { Id = 8, Category = "Desserts", Title = "Banana Ice Cream",
                Ingredients = "4 ripe bananas, frozen\n2 tbsp peanut butter (optional)\n1 tsp vanilla extract",
                Steps = "1. Slice bananas and freeze for at least 2 hours.\n2. Blend frozen bananas in a food processor until creamy.\n3. Add peanut butter and vanilla, blend again.\n4. Serve immediately or freeze for firmer texture." },
        };
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalStars += stars;
            recipe.RatingCount++;
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star-btn @(star <= _selectedRating ? "selected" : "")"
                @onclick="() => SubmitRating(star)"
                disabled="@_hasRated"
                title="@star stars">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    @if (_hasRated)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    <span class="rating-avg">
        Avg: @AverageRating.ToString("F1") (@RatingCount ratings)
    </span>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _hasRated;

    private void SubmitRating(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    margin: 1rem 0;
    flex-wrap: wrap;
}

.rating-label {
    margin-right: 0.5rem;
    font-weight: 500;
}

.star-btn {
    background: none;
    border: none;
    font-size: 1.75rem;
    cursor: pointer;
    color: #ccc;
    padding: 0 2px;
    transition: color 0.15s;
}

.star-btn:hover:not(:disabled) {
    color: #f5a623;
}

.star-btn.selected {
    color: #f5a623;
}

.star-btn:disabled {
    cursor: default;
}

.rating-thanks {
    color: #28a745;
    font-weight: 500;
    margin-left: 0.5rem;
}

.rating-avg {
    margin-left: auto;
    color: #666;
    font-size: 0.9rem;
}

