arguments.new_str:
@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-4">
    <h1>🍳 Welcome to RecipeShare</h1>
    <p class="lead">Discover and share delicious recipes with our community.</p>
</div>

<h2>Browse by Category</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-4 mt-2">
    @foreach (var category in categories)
    {
        <div class="col">
            <div class="card h-100 text-center">
                <div class="card-body">
                    <h3 class="card-title">
                        @(category switch
                        {
                            "Breakfast" => "🥞",
                            "Lunch" => "🥗",
                            "Dinner" => "🍝",
                            "Desserts" => "🍪",
                            _ => "🍽️"
                        })
