toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeShare.Services
@using RecipeShare.Models

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">← Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="recipes/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h1>@recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@recipe.Category</span>

    <StarRating RecipeId="@recipe.Id"
                AverageRating="@recipe.AverageRating"
                RatingCount="@recipe.RatingCount" />

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-header"><strong>🧾 Ingredients</strong></div>
                <div class="card-body">
                    <ul class="mb-0">
                        @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                        {
                            <li>@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
        </div>
        <div class="col-md-8">
            <div class="card">
                <div class="card-header"><strong>👨‍🍳 Steps</strong></div>
                <div class="card-body">
                    @foreach (var step in recipe.Steps.Split('\n'))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>

    <a href="recipes/@recipe.Category" class="btn btn-outline-secondary mt-4">← Back to @recipe.Category</a>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe "@_title" has been added.
        <a href="recipes/@_category">View it in @_category →</a>
    </div>
    <button class="btn btn-primary" @onclick="Reset">Submit Another</button>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label" for="title">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="category">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="ingredients">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;
    private string _category = string.Empty;

    private void HandleSubmit()
    {
        RecipeService.AddRecipe(_model.Title, _model.Category, _model.Ingredients, _model.Steps);
        _title = _model.Title;
        _category = _model.Category;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

